using System;
using System.Collections.Generic;
using System.Linq;
using AICad.Contracts;
using Autodesk.AutoCAD.ApplicationServices;
using Autodesk.AutoCAD.DatabaseServices;
using Autodesk.AutoCAD.EditorInput;
using Autodesk.AutoCAD.Geometry;
using Autodesk.AutoCAD.Runtime;
using AcApp=Autodesk.AutoCAD.ApplicationServices.Core.Application;
[assembly:CommandClass(typeof(AICad.Bridge.PhaseDemo))]
namespace AICad.Bridge;
public sealed class PhaseDemo {
 internal static ObjectId Definition(Database db,Transaction tx){var bt=(BlockTable)tx.GetObject(db.BlockTableId,OpenMode.ForRead);if(bt.Has("AI_TASK"))return bt["AI_TASK"];bt.UpgradeOpen();var def=new BlockTableRecord{Name="AI_TASK"};var id=bt.Add(def);tx.AddNewlyCreatedDBObject(def,true);var pl=new Polyline(4);foreach(var p in new[]{new Point2d(0,0),new Point2d(10000,0),new Point2d(10000,10000),new Point2d(0,10000)})pl.AddVertexAt(pl.NumberOfVertices,p,0,0,0);pl.Closed=true;def.AppendEntity(pl);tx.AddNewlyCreatedDBObject(pl,true);int i=0;foreach(string tag in new[]{"TASK_ID","SKILL_ID","TEMPLATE_ID","STATUS","DEPENDS_ON","PROMPT","SOURCE_REF","PRIORITY"}){var a=new AttributeDefinition{Tag=tag,Prompt=tag,Height=100,Position=new Point3d(200,200+i++*150,0),Invisible=true};def.AppendEntity(a);tx.AddNewlyCreatedDBObject(a,true);}return id;}
 internal static void Insert(Database db,Transaction tx,ObjectId defId,double x,double y,string task,string skill,string template,string dependency=""){var bt=(BlockTable)tx.GetObject(db.BlockTableId,OpenMode.ForRead);var ms=(BlockTableRecord)tx.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForWrite);var block=new BlockReference(new Point3d(x,y,0),defId);ms.AppendEntity(block);tx.AddNewlyCreatedDBObject(block,true);var values=new Dictionary<string,string>{{"TASK_ID",task},{"SKILL_ID",skill},{"TEMPLATE_ID",template},{"STATUS","PENDING"},{"DEPENDS_ON",dependency},{"PROMPT","P0-P6 acceptance fixture"},{"SOURCE_REF",""},{"PRIORITY","0"}};var def=(BlockTableRecord)tx.GetObject(defId,OpenMode.ForRead);foreach(ObjectId id in def)if(tx.GetObject(id,OpenMode.ForRead) is AttributeDefinition a){var r=new AttributeReference();r.SetAttributeFromBlock(a,block.BlockTransform);r.TextString=values.TryGetValue(a.Tag,out string v)?v:"";block.AttributeCollection.AppendAttribute(r);tx.AddNewlyCreatedDBObject(r,true);}}
 internal static void Populate(Database db,Transaction tx){db.Insunits=UnitsValue.Millimeters;var def=Definition(db,tx);Insert(db,tx,def,0,0,"T001","INSERT_DOOR_AXIS_DEMO","STARTER");Insert(db,tx,def,12000,0,"T002","INSERT_DOOR_AXIS_DEMO","STARTER","T001");Insert(db,tx,def,24000,0,"T003","INSERT_DOOR_AXIS_DEMO","STARTER");Insert(db,tx,def,0,12000,"CHAT","CAD_TOOLS","ARCHITECTURE");Insert(db,tx,def,12000,12000,"STAIR","STAIR_SECTION","ARCHITECTURE");Insert(db,tx,def,24000,12000,"WC","WC_SECTION","ARCHITECTURE");Insert(db,tx,def,36000,12000,"SECTION","BUILDING_SECTION","ARCHITECTURE");Insert(db,tx,def,0,24000,"PDF","SOURCE_FLOORPLAN","ARCHITECTURE");Insert(db,tx,def,12000,24000,"SCAN","SOURCE_FLOORPLAN","ARCHITECTURE");var bt=(BlockTable)tx.GetObject(db.BlockTableId,OpenMode.ForRead);var ms=(BlockTableRecord)tx.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForWrite);foreach(var data in new[]{new double[]{0,-4000,6060,1000},new double[]{12000,-4000,3400,2200},new double[]{24000,-4000,6000,4200}}){var pl=new Polyline(4);foreach(var p in new[]{new Point2d(data[0],data[1]),new Point2d(data[0]+data[2],data[1]),new Point2d(data[0]+data[2],data[1]+data[3]),new Point2d(data[0],data[1]+data[3])})pl.AddVertexAt(pl.NumberOfVertices,p,0,0,0);pl.Closed=true;pl.ColorIndex=2;ms.AppendEntity(pl);tx.AddNewlyCreatedDBObject(pl,true);}}
 [CommandMethod("AICADP0P6DEMO",CommandFlags.Session)]public void Demo(){try{var d=AcApp.DocumentManager.Add("");AcApp.DocumentManager.MdiActiveDocument=d;using(var locked=d.LockDocument())using(var tx=d.Database.TransactionManager.StartTransaction()){Populate(d.Database,tx);tx.Commit();}d.SendStringToExecute("_ZOOM _E\n",true,false,false);d.Editor.WriteMessage("\nNew P0-P6 fixture: nine tasks and three source outlines. Yellow outlines are synthetic source references; first is 6060 x 1000 stair footprint.");}catch(System.Exception e){AcApp.DocumentManager.MdiActiveDocument?.Editor.WriteMessage("\nAI CAD: "+e.Message);}}
 [CommandMethod("AICADTASK",CommandFlags.Modal)]public void Task(){var d=AcApp.DocumentManager.MdiActiveDocument;if(d==null)return;try{var position=d.Editor.GetPoint("\nTask origin in WCS XY: ");if(position.Status!=PromptStatus.OK)return;var skill=d.Editor.GetString(new PromptStringOptions("\nSkill ID <CAD_TOOLS>: "){AllowSpaces=false});if(skill.Status!=PromptStatus.OK)return;string id="TASK_"+Guid.NewGuid().ToString("N").Substring(0,8);string sid=string.IsNullOrWhiteSpace(skill.StringResult)?"CAD_TOOLS":skill.StringResult;AICad.Contracts.Json.Name(sid);using var tx=d.Database.TransactionManager.StartTransaction();var def=Definition(d.Database,tx);string template=new ContentStore(Plugin.Current!.Config.ContentRoot).Skill(sid).TemplateId;Insert(d.Database,tx,def,position.Value.X,position.Value.Y,id,sid,template);OutputAnchors.Create(d.Database,tx,id,position.Value);tx.Commit();d.Editor.WriteMessage("\nCreated "+id+". Boundary is 10000 x 10000 mm; transform block if needed.");}catch(System.Exception e){d.Editor.WriteMessage("\nAI CAD: "+e.Message);}}
}
